from fastapi import FastAPI, Body
from pydantic import BaseModel, ConfigDict
from fastapi.testclient import TestClient

class MyType:
    def __init__(self, name: str):
        self.name = name
    def __repr__(self):
        return f"MyType(name={self.name})"

class MyModel(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)
    foo: MyType

app = FastAPI()

@app.post("/single")
def single(item: MyModel):
    return item

@app.post("/multiple")
def multiple(item: MyModel, other: int):
    return {"item": item, "other": other}

client = TestClient(app)

def test_single():
    print("Testing single body parameter...")
    # This should work because FastAPI uses the model directly
    # Actually, let's see.
    try:
        # We can't easily send MyType in JSON, so we'll send a dict
        # and see if Pydantic can instantiate it.
        # But MyType is not a Pydantic model, so Pydantic won't instantiate it
        # unless we have a validator.
        # Let's use a simpler arbitrary type that Pydantic can handle or just check if it crashes during startup/request.
        response = client.post("/single", json={"foo": "some value"})
        print(f"Response: {response.status_code}, {response.json()}")
    except Exception as e:
        print(f"Error: {e}")

def test_multiple():
    print("Testing multiple body parameters...")
    try:
        response = client.post("/multiple", json={"item": {"foo": "some value"}, "other": 1})
        print(f"Response: {response.status_code}, {response.json()}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    test_single()
    test_multiple()

