        # but it doesn't magically make Pydantic know how to parse JSON into that type.
        # It just means it won't raise a SchemaGenerationError.
        response = client.post("/single", json={"foo": "some value"})
        print(f"Response: {response.status_code}, {response.json()}")
    except Exception as e:
