from fastapi import FastAPI
from fastapi.testclient import TestClient

class MyType:
    pass

app = FastAPI()

@app.post("/single")
def single(foo: MyType):
    return {"foo": foo}

client = TestClient(app)

def test_single():
    print("Testing single body parameter with arbitrary type...")
    try:
        response = client.post("/single", json={"foo": "some value"})
        print(f"Response: {response.status_code}, {response.json()}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    test_single()

from pydantic import TypeAdapter, ConfigDict
from typing import Annotated

class MyType:
    pass

try:
    adapter = TypeAdapter(MyType, config=ConfigDict(arbitrary_types_allowed=True))
    print("TypeAdapter with config worked!")
except TypeError as e:
    print(f"TypeAdapter with config failed: {e}")

try:
    adapter = TypeAdapter(Annotated[MyType, ConfigDict(arbitrary_types_allowed=True)])
    print("TypeAdapter with Annotated ConfigDict worked!")
except Exception as e:
    print(f"TypeAdapter with Annotated ConfigDict failed: {e}")

